package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.*;
import com.shatteredpixel.shatteredpixeldungeon.apd.ArcanaInfoDisplay;

/** Spell resource and selected effect rules; never casts, selects a target or queries attack skill. */
public final class SpellExplanation {
    private SpellExplanation() {}
    private static String n(float value){return ObfuscationExplanation.number(value);}
    private static String powerPercent(float power){double value=100d*power;return com.shatteredpixel.shatteredpixeldungeon.messages.Messages.decimalFormat(Math.abs(value)>=1000000?"0.##E0":"0.##",value);}
    /** UI metadata mirrors the game's learned-spell list; never changes availability. */
    public static ClericSpell spellForTalent(Talent talent){
        if(talent==null)return null;
        switch(talent){
            case HOLY_INTUITION:return HolyIntuition.INSTANCE;
            case SHIELD_OF_LIGHT:return ShieldOfLight.INSTANCE;
            case RECALL_INSCRIPTION:return RecallInscription.INSTANCE;
            case SUNRAY:return Sunray.INSTANCE;
            case DIVINE_SENSE:return DivineSense.INSTANCE;
            case BLESS:return BlessSpell.INSTANCE;
            case CLEANSE:return Cleanse.INSTANCE;
            case HOLY_LANCE:return HolyLance.INSTANCE;
            case HALLOWED_GROUND:return HallowedGround.INSTANCE;
            case MNEMONIC_PRAYER:return MnemonicPrayer.INSTANCE;
            case LAY_ON_HANDS:return LayOnHands.INSTANCE;
            case AURA_OF_PROTECTION:return AuraOfProtection.INSTANCE;
            case WALL_OF_LIGHT:return WallOfLight.INSTANCE;
            case DIVINE_INTERVENTION:return DivineIntervention.INSTANCE;
            case JUDGEMENT:return Judgement.INSTANCE;
            case FLASH:return Flash.INSTANCE;
            case BODY_FORM:return BodyForm.INSTANCE;
            case MIND_FORM:return MindForm.INSTANCE;
            case SPIRIT_FORM:return SpiritForm.INSTANCE;
            case BEAMING_RAY:return BeamingRay.INSTANCE;
            case LIFE_LINK:return LifeLinkSpell.INSTANCE;
            case STASIS:return Stasis.INSTANCE;
            default:return null;
        }
    }
    public static String talentDetails(Talent talent,Hero hero){
        if(hero==null||hero.heroClass!=HeroClass.CLERIC||!hero.hasTalent(talent))return "";
        ClericSpell spell=spellForTalent(talent);
        return spell==null?"":"_Spell details_\n"+details(spell,hero);
    }

    public static String summary(ClericSpell spell,Hero hero){
        if(hero==null)return "Spell cost depends on the active character.";
        return "Tome charge cost: "+n(spell.chargeUse(hero))+".";
    }
    public static String details(ClericSpell spell,Hero hero) {
        String effect=effects(spell,hero);
        return resources(spell,hero)+(effect.isEmpty()?"":"\n\n"+effect);
    }
    private static String resources(ClericSpell spell,Hero hero){
        if(hero==null)return "";
        float cost=spell.chargeUse(hero);
        String text="_Casting cost_\nTome charge cost: _"+n(cost)+"_.";
        if(hero.buff(Talent.SatiatedSpellsTracker.class)!=null&&hero.hasTalent(Talent.SATIATED_SPELLS))text+="\nYour meal bonus is ready: the next spell grants _"+(1+2*hero.pointsInTalent(Talent.SATIATED_SPELLS))+" shield points_, keeping a stronger existing Barrier. An active life-linked powered ally can share the benefit. Formula: 1 + 2 × talent rank.";
        if(hero.subClass==HeroSubClass.PALADIN)text+="\nOther spells extend Holy Weapon and Holy Ward by _10 turns per Tome charge spent_, up to 100 turns remaining. Longer existing effects are kept. Direct recasts can exceed this extension limit.";
        AscendedForm.AscendBuff ascended=hero.buff(AscendedForm.AscendBuff.class);
        if(ascended!=null)text+="\nAscended Form spell count: _"+ascended.spellCasts+"_. This cast adds 1 to the count and _"+(int)(10*cost)+" shield points_, subject to the form's shielding rules. Shielding = 10 × Tome charge cost, rounded down. Judgement resets the spell count after casting.";
        return text;
    }
    public static String effects(ClericSpell spell,Hero hero) {
        if(hero==null)return "";
        AscendedForm.AscendBuff ascended=hero.buff(AscendedForm.AscendBuff.class);
        String text="";
        if(spell instanceof GuidingLight){text+="\n\n_Guiding Light_\nDeals _2–8 base magic damage_ and illuminates survivors. While you are a Cleric, illuminated monsters normally cannot dodge attacks. Your weapon's strength requirement must be met; special guard and dodge rules still apply. The first successful attack consumes Illumination.";if(hero.hasTalent(Talent.SEARING_LIGHT))text+=" Your Searing Light adds _"+(1+2*hero.pointsInTalent(Talent.SEARING_LIGHT))+" damage_ to your hit (1 + 2 × talent rank).";if(hero.subClass==HeroSubClass.PRIEST)text+=" When another creature consumes Illumination with an attack, it also deals _"+(hero.lvl+5)+" base magic damage_ (hero level + 5). You get one free Guiding Light cast every _50 turns_; a free cast still takes its normal turn.";}
        else if(spell instanceof ShieldOfLight){int low=1+hero.pointsInTalent(Talent.SHIELD_OF_LIGHT);text+="\n\n_Shield of Light_\nBlocks an extra _"+low+"–"+(2*low)+" damage per hit_ from the chosen enemy, rolling separately for each hit and favoring middle values. Other enemies are unaffected. Choosing another enemy replaces the first. A life-linked powered ally can share the protection.\nBlock range = 1 + talent rank through 2 × (1 + rank). Lasts 5 turns for you, or 4 turns for the linked ally before duration bonuses. Casting is instant.";}
        else if(spell instanceof Sunray){int rank=hero.pointsInTalent(Talent.SUNRAY),low=rank==2?6:4,high=rank==2?12:8;int time=2+2*rank;text+="\n\n_Sunray_\nDeals _"+low+"–"+high+" base magic damage_; undead and demons use the maximum base roll. Its first hit on a surviving target blinds for _"+time+" turns_, adjusted by resistance. Cast again while that Sunray blindness is still active to paralyze for the same duration instead, once per target. Later casts cannot blind that target again.\nBlindness and paralysis duration = 2 + 2 × talent rank.";}
        else if(spell instanceof BlessSpell){int rank=hero.pointsInTalent(Talent.BLESS),amount=5+5*rank;text+="\n\n_Bless_\nOn yourself: _"+(2+4*rank)+" turns of Bless_ and _"+amount+" shield points_. On another creature: _"+amount+" turns of Bless_ and up to _"+amount+" HP_ restored. Unused healing becomes Barrier; a stronger existing Barrier is kept. A life-linked powered ally can share the effect.\nBless raises accuracy and evasion scores by _25%_. The actual chance to hit or dodge still depends on the opponent. Durations and healing follow the target's normal rules.";}
        else if(spell instanceof LayOnHands){int amount=LayOnHands.restorationAmount(hero);text+="\n\n_Lay on Hands_\nOn yourself: adds up to _"+amount+" shield points_, without healing HP. On another character: restores up to _"+amount+" HP_, turning unused healing into added Barrier. Barrier from this spell can stack up to _"+(3*amount)+" shield points_; a stronger existing Barrier is kept.\nRequires a target within _1 tile_. Casts instantly and can share its effect with a life-linked powered ally.\nRestoration = 10 + 5 × talent rank. Added Barrier = max(0, min(unused restoration, "+(3*amount)+" − current Barrier)).";}
        else if(spell instanceof Cleanse){int rank=hero.pointsInTalent(Talent.CLEANSE),duration=Math.max(0,2*(rank-1)),shield=10*rank;text+="\n\n_Cleanse_\nRemoves harmful statuses from you and visible allies, including your life-linked powered ally outside sight. It does not remove ally-conversion effects or Lost Inventory, recover a lost backpack, uncurse equipment, or heal HP. Grants _"+shield+" shield points_, keeping a stronger existing Barrier.";if(duration>0)text+=" Also prevents eligible harmful statuses for _"+(duration+1)+" turns_ on the standard timer. This does not prevent direct damage.";text+="\nShielding = 10 × talent rank. Protection timer = 2 × (rank − 1), plus the following status update, when rank is above 1. Casting takes _1 turn_.";}
        else if(spell instanceof Radiance){text+="\n\n_Radiance_\nIlluminates visible non-allied monsters, including neutral creatures. Already illuminated targets instead take _"+(hero.lvl+5)+" base magic damage_ before defenses (hero level + 5). The first cast does not damage an unilluminated target. Surviving active targets are paralyzed for _3 turns_, adjusted by resistance.\nOn floors with a base sight range below 6 tiles, also grants _"+(com.shatteredpixel.shatteredpixeldungeon.Dungeon.isChallenged(com.shatteredpixel.shatteredpixeldungeon.Challenges.DARKNESS)?20:100)+" turns of Light_. Costs _1 turn_.";}
        else if(spell instanceof Flash){int count=ascended==null?0:ascended.flashCasts;text+="\n\n_Flash_\nRequires Ascended Form. Teleports up to _"+Flash.maximumDistance(hero)+" tiles_ to a mapped or visited, non-solid tile. Requires an unoccupied destination connected by traversable terrain; a straight line of sight is not needed.\nFlash casts in this form: _"+count+"_. Current Tome charge cost: _"+n(spell.chargeUse(hero))+"_ (2 + previous Flash casts). A successful teleport takes _1 turn_ and raises the next cast's cost by 1. Invalid or cancelled attempts spend nothing. Refreshing the same form does not reset the count. Range = 2 + talent rank.";}
        else if(spell instanceof DivineIntervention){int shield=DivineIntervention.shieldOffer(hero),rank=hero.pointsInTalent(Talent.DIVINE_INTERVENTION);text+="\n\n_Divine Intervention_\nGrants _"+shield+" shield points_ to your Ascended Form and allies, including those outside sight. Keeps stronger existing shields. Your form's ordinary cast-shield bonus is applied first; the result is raised to at least "+shield+", rather than adding another "+shield+" on top.\nExtends Ascended Form by _"+(2+rank)+" turns_. Usable _once per form_; refreshing the same form does not reset it. Allies lose this protection when your form ends. Costs _1 turn_ and _5 Tome charges_.\nShielding = 100 + 50 × talent rank; form extension = 2 + rank.";}
        else if(spell instanceof HolyIntuition){text+="\n\n_Holy Intuition_\nReveals whether one equipment item or wand is cursed, without removing the curse or revealing its upgrade level. Requires an unidentified item whose curse status is unknown; consumables are excluded. A valid selection costs _1 turn_; cancelling spends nothing.\nTome charge cost = 4 − talent rank.";}
        else if(spell instanceof RecallInscription){text+="\n\n_Recall Inscription_\nRepeats the last recorded scroll or runestone effect, then consumes the record. Upgrade scrolls do not replace the record. Recalled scrolls do not trigger on-read talent bonuses. The recalled item keeps its own targeting and action time.\n_Recall window_\nRank 1: _10 turns_. Rank 2: _300 turns_. A new qualifying use replaces the recorded item and keeps the longer remaining timer. Requires a record to cast.\n_Tome charge costs_\nScrolls: 3; Transmutation: 6. Exotic scrolls: 4; Metamorphosis and Enchantment: 8. Runestones: 2; Augmentation and Enchantment stones: 4.";}
        else if(spell instanceof BodyForm){int duration=Math.round(13.33f+6.67f*hero.pointsInTalent(Talent.BODY_FORM));text+="\n\n_Trinity: Body Form_\nStores a discovered enchantment or glyph for Trinity, without changing your equipment. Activating it grants that effect for _"+duration+" turns_, with its usual triggers and restrictions. The Tome pays for changing the selection; activation uses armor ability charge.\nDuration = round(13.33 + 6.67 × talent rank).";}
        else if(spell instanceof MindForm){int level=2+hero.pointsInTalent(Talent.MIND_FORM);text+="\n\n_Trinity: Mind Form_\nStores a discovered wand or thrown-weapon type, including tipped darts. Activating it uses a _+"+level+" version_ of that effect, with its normal targeting and collision rules. Your inventory items are not upgraded. The Tome pays for changing the selection; activation uses armor ability charge.\nEffect level = 2 + talent rank.";}
        else if(spell instanceof SpiritForm){int rank=hero.pointsInTalent(Talent.SPIRIT_FORM);text+="\n\n_Trinity: Spirit Form_\nStores a discovered ring or artifact, excluding the Holy Tome. Activating it uses a _+"+rank+" ring_ or _+"+(2+2*rank)+" artifact_, with the chosen item's usual effect. Artifact levels use the normal 0–10 scale. Passive effects last _"+n(SpiritForm.SpiritFormBuff.DURATION)+" turns_; active artifact effects follow their own rules. The Tome pays for changing the selection; activation uses armor ability charge.\nRing level = talent rank. Artifact level = 2 + 2 × talent rank.";}
        else if(spell instanceof LifeLinkSpell){int rank=hero.pointsInTalent(Talent.LIFE_LINK);text+="\n\n_Empowered Life Link_\nLinks you and your powered ally for _"+LifeLinkSpell.linkDuration(hero)+" turns_, sharing attacks and most other incoming damage. Starvation is not shared. Each share is rounded up; remaining damage protections apply separately.\nYour ally's Power of Many reduces its incoming damage by _"+(30+5*rank)+"%_ at that step, replacing the usual 25%. Shield of Light, Divine Sense, Bless, Cleanse, Lay on Hands, Hallowed Ground, Mnemonic Prayer and the meal-shield bonus can also share their effects. A link can be prepared for an ally in Stasis; sharing resumes when it is released.\nDuration = round(6.67 + 3.33 × talent rank). Damage share = round up(incoming damage ÷ (valid links + 1)). Casting takes _1 turn_.";}
        else if(spell instanceof BeamingRay){int rank=hero.pointsInTalent(Talent.BEAMING_RAY);text+="\n\n_Beaming Ray_\nMoves your powered ally up to _"+BeamingRay.movementRange(hero,false)+" tiles_ from its position, or _"+BeamingRay.movementRange(hero,true)+" tiles_ if immovable. A stored ally measures from your position instead. Needs a visible, suitable destination; an occupied or blocked selection can redirect to a free neighboring tile.\nChoose an enemy to direct the ally toward it. Otherwise it selects a hostile within 4 tiles of landing, favoring more distant candidates. Against that directed target, Power of Many grants _"+(30+5*rank)+"% more attack damage_ for _"+n(BeamingRay.BeamingRayBoost.DURATION)+" turns_, replacing the usual 25%. Normal hit checks and defenses still apply.\nRange = 4 × talent rank, halved for immovable allies. Directed-target damage bonus = 30 + 5 × rank percent. Costs _1 turn_.";}
        else if(spell instanceof Stasis){int duration=30+30*hero.pointsInTalent(Talent.STASIS);text+="\n\n_Stasis_\nStores your powered ally for _"+duration+" turns_. Positive effects and effects retained through revival are preserved while stored; other effects may end. The stored ally and its retained state survive saving and loading.\nStoring costs _2 Tome charges_ and _1 turn_. Recast to release for free, instantly; releasing still counts as casting a spell and can consume a ready spell bonus. Leave a free neighboring tile: without one, release may put the ally on an occupied or blocked tile. Immovable allies are released before changing floors.\nStorage duration = 30 + 30 × talent rank.";}
        else if(spell instanceof HallowedGround){int rank=hero.pointsInTalent(Talent.HALLOWED_GROUND);text+="\n\n_Hallowed Ground_\nCovers reachable floor within _"+rank+" tiles_ of a visible chosen point, up to _"+(1+2*rank)+" tiles across_ in open ground. Walls restrict the shape. Lasts _20 turns_ unless fire destroys it.\nInitially, you and full-health allies gain up to _"+HallowedGround.INITIAL_POWER+" Barrier_, limited by _"+HallowedGround.INITIAL_SHIELD_LIMIT+" total shielding_. Casting above that limit can reduce Barrier. Injured other allies instead heal up to _"+HallowedGround.INITIAL_POWER+" HP_, converting unused healing to Barrier without that initial limit.\nEach turn, you and full-health allies gain _1 Barrier_; injured other allies heal _1 HP_. This ongoing Barrier has no initial cap. Grounded non-allied creatures are illuminated and rooted for _2 turns_, then repeatedly crippled while not rooted. Life Link shares the friendly effect when only one linked character is in the area.\n_Grass growth_\nEach eligible grass tile has a _"+n(100f/HallowedGround.grassGrowthDenominator(hero))+"% chance per turn_ to grow tall. Formula: 1 ÷ (10 + 10 × rank). Disabled passive recovery or repeated use without experience can produce furrowed grass instead.\nInitial Barrier change = min("+HallowedGround.INITIAL_POWER+", "+HallowedGround.INITIAL_SHIELD_LIMIT+" − total shielding). Casting takes _1 turn_.";}
        else if(spell instanceof WallOfLight){int rank=hero.pointsInTalent(Talent.WALL_OF_LIGHT);text+="\n\n_Wall of Light_\nCreates up to _"+(1+2*rank)+" panels_ straight across, or _"+(1+4*rank)+"_ in a diagonal staircase. Walls and floor edges limit placement. Panels last _20 turns_ and block movement and projectiles, while allowing sight. Enemies caught when the wall forms are pushed up to _1 tile_ and briefly paralyzed according to their next action time.\nCreating a wall costs _3 Tome charges_ and _1 turn_. Recast while a Light Wall exists to remove it for free, instantly. Removal does not trigger spell-cast bonuses.\nStraight length = 1 + 2 × rank. Diagonal length = 1 + 4 × rank.";}
        else if(spell instanceof MnemonicPrayer){int amount=2+hero.pointsInTalent(Talent.MNEMONIC_PRAYER);text+="\n\n_Mnemonic Prayer_\nExtends many positive effects on a visible ally, or negative effects on another visible creature. Other creatures are also illuminated. Each active effect can benefit only once.\nMost timed effects gain _"+amount+" turns_, adjusted by their normal duration rules. Adds _"+amount+" base HP_ to Healing and Sungrass reserves, before healing modifiers. Greater Haste gains up to _"+amount+" extra steps_; passing turns can use them too. Bleeding gains _"+amount+" base damage_ on its next tick, with later ticks weakening normally. Shields keep their amount but postpone fading by _"+amount+" turns_.\nAscended Form, Body/Spirit Form, Power of Many, Beaming Ray's boost and Life Link are excluded from friendly extension. Life Link can share supported effects with your powered ally. Casting is instant.\nExtension amount = 2 + talent rank.";}
        else if(spell instanceof DivineSense){int rank=hero.pointsInTalent(Talent.DIVINE_SENSE);if(hero.heroClass==HeroClass.CLERIC)text+="\n\n_Divine Sense_\nSenses creatures within _"+(4+4*rank)+" tiles_ for _"+n(DivineSense.DivineSenseTracker.DURATION)+" turns_. Casts instantly and can share the effect with a life-linked powered ally. It does not map rooms or let attacks pass through walls.\nSensing range = 4 + 4 × talent rank.";else text+="\n\n_Divine Sense: alternate talent_\nBriefly senses creatures within _"+(1+2*rank)+" tiles_ after using a wand or artifact. This is the alternate talent effect, not the Cleric's 50-turn spell.\nSensing range = 1 + 2 × talent rank.";}
        else if(spell instanceof HolyLance){int rank=hero.pointsInTalent(Talent.HOLY_LANCE),low=15+15*rank,high=Math.round(27.5f+27.5f*rank);text+="\n\n_Holy Lance_\nDeals _"+low+"–"+high+" base magic damage_; undead and demons use the maximum base roll. Takes _1 turn_, then has a _30-turn cooldown_. Firing at an empty valid location still spends time and charges.\nMinimum damage = 15 + 15 × rank. Maximum = round(27.5 + 27.5 × rank).";}
        else if(spell instanceof Smite){int low=5+hero.lvl/2,high=10+hero.lvl;float current=EnchantmentExplanation.knownPower(hero);text+="\n\n_Smite_\nAdds _"+low+"–"+high+" base magic damage_ on a hit; undead and demons take the maximum. Requires a target within normal attack reach and uses your normal attack time. Accuracy is greatly increased when your weapon's strength requirement is met, but special dodges can still avoid it.\nAdds _300% of normal enchantment power_ to the strike, on top of existing power. Each enchantment keeps its own chance, strength and limits. ";if(hero.buff(MagicImmune.class)!=null)text+="Magic immunity currently suppresses the armed spell bonus and enchantment effects; the separate unarmed bonus remains active.";else if(Float.isFinite(current))text+="Enchantment power for this strike: _"+powerPercent(current+(hero.buff(Smite.SmiteTracker.class)==null?3:0))+"% of normal_.";else text+="Identify your rings to preview the combined power.";text+="\nMagic damage range = 5 + half your level, rounded down, through 10 + your level.";}
        else if(spell instanceof Judgement){int base=5+5*hero.pointsInTalent(Talent.JUDGEMENT),count=ascended==null?0:ascended.spellCasts,total=base+Math.round(base*count/3f);text+="\n\n_Judgement_\nDeals _"+total+"–"+(2*total)+" base magic damage_ to each visible non-allied creature, including neutral creatures. More spells cast during Ascended Form strengthen it. Current recorded casts: _"+count+"_. Casting takes _1 turn_ and resets the count.\nBase minimum = 5 + 5 × rank = "+base+". Current minimum = base + round(base × recorded casts ÷ 3). Maximum = twice that minimum. Damage modifiers and defenses apply afterward.";}
        else if(spell instanceof AuraOfProtection){int rank=hero.pointsInTalent(Talent.AURA_OF_PROTECTION);float remain=.9f-.1f*rank,add=.25f+.25f*rank;float ring=ArcanaInfoDisplay.knownArcanaPower(hero);text+="\n\n_Aura of Protection_\nReduces incoming damage by _"+Math.round(100*(1-remain))+"%_ before rounding and remaining protection, for you and allies within _2 tiles_. A life-linked powered ally can benefit outside that range. Lasts _"+n(AuraOfProtection.AuraBuff.DURATION)+" turns_.\nAdds _"+Math.round(100*add)+"% of normal glyph power_ alongside Arcana, rather than multiplying Arcana's bonus. ";if(hero.buff(MagicImmune.class)!=null)text+="Magic immunity currently suppresses your worn glyph effects.";else if(Float.isFinite(ring))text+="Combined glyph power: _"+powerPercent(ring+add)+"% of normal_.";else text+="Identify your rings to preview combined glyph power.";text+=" An ally does not trigger the same glyph twice.\nDamage remaining = 0.9 − 0.1 × rank. Added glyph power = 25 + 25 × rank percent of normal.";}
        else if(spell instanceof HolyWeapon){int base=hero.subClass==HeroSubClass.PALADIN?6:2;float power=EnchantmentExplanation.knownPower(hero);text+="\n\n_Holy Weapon_\nWeapon and unarmed hits add magic damage to surviving targets. Base bonus: _"+base+" damage_, scaled by enchantment power and rounded. ";if(hero.buff(MagicImmune.class)!=null)text+="Magic immunity currently disables the armed bonus; the separate unarmed bonus remains active.";else if(Float.isFinite(power))text+="Current bonus: _"+Math.round(base*power)+" base magic damage_ before defenses.";else text+="Identify your rings to preview the combined bonus.";text+="\nLasts _"+n(HolyWeapon.HolyWepBuff.DURATION)+" turns_ and casts instantly. Temporarily replaces a beneficial weapon enchantment, except for the Paladin; weapon curses are not removed. Direct recasts add duration. Paladin extensions follow the separate limit above.";}
        else if(spell instanceof HolyWard){int base=hero.subClass==HeroSubClass.PALADIN?3:1;float ring=ArcanaInfoDisplay.knownArcanaPower(hero);text+="\n\n_Holy Ward_\nAdds _"+base+" base protection_ against attacks, scaled by glyph power and rounded. ";if(hero.belongings.armor()!=null){if(hero.buff(MagicImmune.class)!=null)text+="Magic immunity currently disables this armor bonus.";else if(Float.isFinite(ring))text+="Current bonus: _"+Math.round(base*(ring+ObfuscationExplanation.aura(hero)))+" damage blocked_ per hit.";else text+="Identify your rings to preview the combined protection.";text+=" Temporarily replaces a beneficial armor glyph, except for the Paladin. Armor curses are not removed.";}else text+="Without armor, protection depends on the attacker's glyph power, so one exact blocking value cannot be previewed.";text+="\nLasts _"+n(HolyWard.HolyArmBuff.DURATION)+" turns_ and casts instantly. Direct recasts add duration. Paladin extensions follow the separate limit above.";}

        return text.trim();
    }
}
